import json
import re
import html
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
references = json.loads(Path('reference-targets.json').read_text())
by_number = {a['number']: a for a in sources}
TAX = 'taxe-creation-bureaux-commerces-stockage-idf-suppression'
LAND = 'urbanisme-reemploi-industriel-fin-autorisation-speciale'
