DATE = "la date d'entrée en vigueur de la loi supprimant la taxe sur la création de bureaux, de locaux commerciaux et de locaux de stockage en Ile-de-France"

def plain(xml):
    return html.unescape(re.sub(r'<[^>]*>', '', xml)).strip()

def paragraphs(*parts):
    return ''.join('<p>' + html.escape(p, quote=False) + '</p>' for p in parts)

def impact(classification, assessment, limitations, burdens, effects):
    return dict(version=1, classification=classification, assessment=assessment,
                scope_limitations=limitations, new_burdens_review=burdens, effects=effects)

def effect(kind, measure, description, before, after, unit, people, transition, replacement, sq, pq):
    return dict(kind=kind, measure_id=measure, description=description,
                before=before, after=after, unit=unit, affected_population=people,
                conditions_and_transition=transition,
                replacement_or_new_burdens=replacement,
                source_quote=sq, proposed_quote=pq)

def base(number, proposed, reason, notes):
    a = by_number[number]
    out = {k: a[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
    out.update(proposed_xml=proposed, reason=reason, review_notes=notes, status='rewrite_draft', reference_checks=[])
    return out

def repeal(number, parts, reason, notes, scope):
    out = base(number, paragraphs(*parts), reason, notes)
    out.update(change_type='full_repeal', repeal_policy_id='editorial_direction_2026_10_19', repeal_scope=scope)
    return out

def reduction(number, parts, reason, notes, removed):
    out = base(number, paragraphs(*parts), reason, notes)
    out.update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=removed)
    return out

